package java.util;import java.util.function.*;
public class HashMap<K,V> extends AbstractMap<K,V> implements Map<K,V>,Cloneable,java.io.Serializable{
 protected static class Node<K,V> extends SimpleEntry<K,V>{final int hash;Node<K,V> next,previous;Node(int hash,K key,V value){super(key,value);this.hash=hash;}}
 protected Node<K,V> first,last;protected int count,modCount;
 public HashMap(){}public HashMap(int capacity){this(capacity,0.75f);}public HashMap(int capacity,float loadFactor){if(capacity<0 || !(loadFactor>0))throw new IllegalArgumentException();}public HashMap(Map<? extends K,? extends V> source){putEntries(source,false);}
 protected boolean keyEquals(Object a,Object b){return Objects.equals(a,b);}protected int keyHash(Object key){return Objects.hashCode(key);}
 protected Node<K,V> find(Object key){return find(keyHash(key),key);}
 protected Node<K,V> find(int hash,Object key){for(Node<K,V> node=first;node!=null;node=node.next)if(hash==node.hash && keyEquals(key,node.getKey()))return node;return null;}
 public int size(){return count;}public boolean containsKey(Object key){return find(key)!=null;}public V get(Object key){Node<K,V> node=find(key);if(node==null)return null;afterAccess(node);return node.getValue();}
 protected void afterAccess(Node<K,V> node){}protected void afterInsert(){}
 public V getOrDefault(Object key,V fallback){Node<K,V> node=find(key);if(node==null)return fallback;afterAccess(node);return node.getValue();}
 public V put(K key,V value){return putValue(keyHash(key),key,value,false,true);}
 public V putIfAbsent(K key,V value){return putValue(keyHash(key),key,value,true,true);}
 private V putValue(int hash,K key,V value,boolean absent,boolean evict){Node<K,V> node=find(hash,key);if(node!=null){V old=node.getValue();if(!absent || old==null)node.setValue(value);afterAccess(node);return old;}insert(hash,key,value,evict);return null;}
 private void insert(int hash,K key,V value,boolean evict){Node<K,V> node=new Node<K,V>(hash,key,value);node.previous=last;if(last==null)first=node;else last.next=node;last=node;count++;modCount++;if(evict)afterInsert();}
 protected final void putEntries(Map<? extends K,? extends V> source,boolean evict){for(Entry<? extends K,? extends V> entry:source.entrySet())putValue(keyHash(entry.getKey()),entry.getKey(),entry.getValue(),false,evict);}
 public void putAll(Map<? extends K,? extends V> source){putEntries(source,true);}
 protected void unlink(Node<K,V> node){if(node.previous==null)first=node.next;else node.previous.next=node.next;if(node.next==null)last=node.previous;else node.next.previous=node.previous;count--;modCount++;}
 public V remove(Object key){Node<K,V> node=find(key);if(node==null)return null;V old=node.getValue();unlink(node);return old;}
 public void clear(){first=last=null;count=0;modCount++;}
 public Set<Entry<K,V>> entrySet(){return new AbstractSet<Entry<K,V>>(){public int size(){return count;}public void clear(){HashMap.this.clear();}public boolean contains(Object value){if(!(value instanceof Entry))return false;Entry<?,?> entry=(Entry<?,?>)value;Node<K,V> node=find(entry.getKey());return node!=null && node.equals(entry);}public boolean remove(Object value){if(!(value instanceof Entry))return false;Entry<?,?> entry=(Entry<?,?>)value;Node<K,V> node=find(entry.getKey());if(node==null || !Objects.equals(entry.getValue(),node.getValue()))return false;unlink(node);return true;}public Iterator<Entry<K,V>> iterator(){return new Iterator<Entry<K,V>>(){Node<K,V> next=first,previous;int expected=modCount;void check(){if(expected!=modCount)throw new ConcurrentModificationException();}public boolean hasNext(){return next!=null;}public Entry<K,V> next(){check();if(next==null)throw new NoSuchElementException();previous=next;next=next.next;return previous;}public void remove(){if(previous==null)throw new IllegalStateException();check();unlink(previous);previous=null;expected=modCount;}};}};}
 public Set<K> keySet(){return new AbstractSet<K>(){public int size(){return count;}public boolean contains(Object key){return containsKey(key);}public boolean remove(Object key){Node<K,V> node=find(key);if(node==null)return false;unlink(node);return true;}public void clear(){HashMap.this.clear();}public Iterator<K> iterator(){Iterator<Entry<K,V>> entries=entrySet().iterator();return new Iterator<K>(){public boolean hasNext(){return entries.hasNext();}public K next(){return entries.next().getKey();}public void remove(){entries.remove();}};}};}
 public Object clone(){try{HashMap<K,V> copy=(HashMap<K,V>)super.clone();copy.first=copy.last=null;copy.count=copy.modCount=0;for(Node<K,V> node=first;node!=null;node=node.next){Node<K,V> fresh=new Node<K,V>(node.hash,node.getKey(),node.getValue());fresh.previous=copy.last;if(copy.last==null)copy.first=fresh;else copy.last.next=fresh;copy.last=fresh;copy.count++;}return copy;}catch(CloneNotSupportedException impossible){throw new InternalError();}}
 public V computeIfAbsent(K key,Function<? super K,? extends V> function){Objects.requireNonNull(function);int hash=keyHash(key);Node<K,V> node=find(hash,key);if(node!=null && node.getValue()!=null){afterAccess(node);return node.getValue();}int version=modCount;V value=function.apply(key);if(version!=modCount)throw new ConcurrentModificationException();if(value!=null){if(node==null)insert(hash,key,value,true);else{node.setValue(value);afterAccess(node);}}return value;}
 public V computeIfPresent(K key,BiFunction<? super K,? super V,? extends V> function){Objects.requireNonNull(function);Node<K,V> node=find(key);if(node==null || node.getValue()==null)return null;int version=modCount;V value=function.apply(key,node.getValue());if(version!=modCount)throw new ConcurrentModificationException();if(value==null)unlink(node);else{node.setValue(value);afterAccess(node);}return value;}
 public V compute(K key,BiFunction<? super K,? super V,? extends V> function){Objects.requireNonNull(function);int hash=keyHash(key);Node<K,V> node=find(hash,key);int version=modCount;V value=function.apply(key,node==null?null:node.getValue());if(version!=modCount)throw new ConcurrentModificationException();if(value==null){if(node!=null)unlink(node);}else if(node==null)insert(hash,key,value,true);else{node.setValue(value);afterAccess(node);}return value;}
 public V merge(K key,V value,BiFunction<? super V,? super V,? extends V> function){Objects.requireNonNull(value);Objects.requireNonNull(function);int hash=keyHash(key);Node<K,V> node=find(hash,key);if(node==null){insert(hash,key,value,true);return value;}V result=value;if(node.getValue()!=null){int version=modCount;result=function.apply(node.getValue(),value);if(version!=modCount)throw new ConcurrentModificationException();}if(result==null)unlink(node);else{node.setValue(result);afterAccess(node);}return result;}
 public boolean remove(Object key,Object value){Node<K,V> node=find(key);if(node==null || !Objects.equals(node.getValue(),value))return false;unlink(node);return true;}
 public boolean replace(K key,V old,V value){Node<K,V> node=find(key);if(node==null || !Objects.equals(old,node.getValue()))return false;node.setValue(value);afterAccess(node);return true;}
 public V replace(K key,V value){Node<K,V> node=find(key);if(node==null)return null;V old=node.setValue(value);afterAccess(node);return old;}
 public void forEach(BiConsumer<? super K,? super V> action){Objects.requireNonNull(action);int version=modCount;for(Node<K,V> node=first;node!=null;node=node.next){action.accept(node.getKey(),node.getValue());if(version!=modCount)throw new ConcurrentModificationException();}}
 public void replaceAll(BiFunction<? super K,? super V,? extends V> function){Objects.requireNonNull(function);int version=modCount;for(Node<K,V> node=first;node!=null;node=node.next){V value=function.apply(node.getKey(),node.getValue());node.setValue(value);if(version!=modCount)throw new ConcurrentModificationException();}}
}
